function urlMetaer() {
	url = "https://archivos.meteochile.gob.cl/portaldmc/meteochile";
	return url;
}

function urlHomeMeteoChile() {
	return "https://www.meteochile.gob.cl/PortalDMC-web";
}

function urlLocalJs(){
	url = "https://archivos.meteochile.gob.cl/portaldmc/localJS";
	return url;
}


var navegacion = new Array();

function cargarComponente(url){
	navegacion[navegacion.length]= url;
	if(url.indexOf("?")>0){
		url = url + "&"+Math.random();
	}
	else{
		url = url +"?"+Math.random();
	}

	$("#visor_componente").attr("src",url);
	$("#visor_componente").load(function(){

		setTimeout(function(){ocultarCargando();},100);
    });
}

function cargarComponenteFooter(url){
	navegacion[navegacion.length]= url;
	if(url.indexOf("?")>0){
		url = url + "&" + Math.random();
	}
	else{
		url = url +"?"+Math.random();
	}

	$("#visor_componente").attr("src",url);
	$("#visor_componente").load(function(){

		setTimeout(function(){ocultarCargando();},100);
    });
}

function ajustarVisorPadre(width,height){

	$("#visor_componente").animate({height:height+"px",width:width+"px"},100);

}

function volver(){
	if(navegacion[navegacion.length-2]!= null)
	cargarComponente(navegacion[navegacion.length-2]);
}

cargarComponente("pronostico_general.xhtml");
function mostrarCargando(){
	$("#cargando").css("height",$("#visor_componente").css("height"));
	$("#cargando").css("width" ,$("#visor_componente").css("width"));

	$("#cargando").css("left" ,$("#visor_componente").offset().left);

	$("#cargando").css("top" ,$("#visor_componente").offset().top);

	$("#cargando").show();
}

function ocultarCargando(){
	$("#cargando").hide();
}
